"use client";
// Blur Hover Reveal: twelve brands rest in a quiet grid. Hover a name (or tab to it) and it comes
// into focus, scaling up and taking its brand colour, while the others recede and blur. With
// `autoplay` the focus walks the grid by itself until the first touch.

import * as React from "react";
import { motion, useInView, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { INK, LOGOS, LogoHeading, LogoLockup, SPRING, type Logo } from "./logos";

export type LogoCloudBlurProps = {
  /** Brands in the grid: { name, Icon, color, wordmark? }. Defaults to twenty invented brands. */
  logos?: Logo[];
  /** Headline above the grid. */
  title?: string;
  /** Line under the headline. Leave empty to hide it. */
  subtitle?: string;
  /** How many marks to show, taken from the start of `logos` (1 to 12). */
  count?: number;
  /** Opacity of the other marks while one is focused. */
  recedeOpacity?: number;
  /** Blur in px on the other marks while one is focused. */
  recedeBlur?: number;
  /** Scale of the focused mark. */
  hoverScale?: number;
  /** Moves the focus along the grid by itself until someone touches it. Pauses off screen and never runs under reduced motion. */
  autoplay?: boolean;
  className?: string;
};

export default function LogoCloudBlur({
  logos = LOGOS,
  title = "The teams behind the products you open every morning.",
  subtitle = "Hover a name to bring it into focus.",
  count = 12,
  recedeOpacity = 0.25,
  recedeBlur = 3,
  hoverScale = 1.08,
  autoplay = false,
  className,
}: LogoCloudBlurProps) {
  const reduced = !!useReducedMotion();
  const ref = React.useRef<HTMLUListElement>(null);
  const inView = useInView(ref, { margin: "-80px" });
  const touched = React.useRef(false);
  const [focus, setFocus] = React.useState<number | null>(null);
  const list = logos.slice(0, Math.max(1, Math.min(12, count)));

  React.useEffect(() => {
    if (!autoplay || reduced || !inView) return;
    let k = 0;
    const id = window.setInterval(() => {
      if (touched.current) return window.clearInterval(id);
      k = (k + 5) % list.length;
      setFocus(k % 3 === 2 ? null : k);
    }, 1200);
    return () => window.clearInterval(id);
  }, [autoplay, reduced, inView, list.length]);

  const touch = () => (touched.current = true);

  return (
    <section className={cn("w-full bg-white px-4 py-16 dark:bg-black sm:py-24", className)} onPointerDown={touch} onPointerMove={touch}>
      <LogoHeading title={title} subtitle={subtitle} />
      <ul
        ref={ref}
        onMouseLeave={() => setFocus(null)}
        className="m-0 mx-auto mt-12 grid max-w-3xl list-none grid-cols-2 place-items-center gap-x-6 gap-y-8 p-0 sm:mt-14 sm:grid-cols-4"
      >
        {list.map((b, i) => {
          const state = focus === null ? "rest" : focus === i ? "focus" : "recede";
          return (
            <li key={b.name}>
              <motion.div
                tabIndex={0}
                aria-label={b.name}
                onHoverStart={() => setFocus(i)}
                onFocus={() => setFocus(i)}
                onBlur={() => setFocus(null)}
                animate={state}
                initial={false}
                variants={{
                  rest: { opacity: 0.8, scale: 1, filter: "blur(0px)" },
                  focus: { opacity: 1, scale: reduced ? 1 : hoverScale, filter: "blur(0px)" },
                  recede: { opacity: recedeOpacity, scale: reduced ? 1 : 0.97, filter: reduced ? "blur(0px)" : `blur(${recedeBlur}px)` },
                }}
                transition={SPRING}
                className={cn("flex cursor-default rounded-lg outline-none focus-visible:ring-2 focus-visible:ring-[#0071e3] focus-visible:ring-offset-4 dark:focus-visible:ring-offset-black", INK)}
              >
                <LogoLockup logo={b} tinted={focus === i} className="text-[19px] sm:text-[21px]" />
              </motion.div>
            </li>
          );
        })}
      </ul>
    </section>
  );
}

"use client";
// Infinite Marquee: two rows of brands drift in opposite directions at slightly different speeds,
// faded out at both edges. Hover a row and it eases to a stop, then picks up again. Pure
// requestAnimationFrame, no marquee package; it stops while off screen and under reduced motion.

import * as React from "react";
import { useInView } from "framer-motion";
import { cn } from "@/lib/utils";
import { EDGE, LOGOS, LogoHeading, LogoLockup, Track, type Logo } from "./logos";

export type LogoCloudMarqueeProps = {
  /** Brands to scroll: { name, Icon, color, wordmark? }. Defaults to twenty invented brands. */
  logos?: Logo[];
  /** Small grey label above the headline. Leave empty to hide it. */
  eyebrow?: string;
  /** Headline above the band. */
  title?: string;
  /** Drift speed of the first row, in px per second. The second row is a little slower. */
  speed?: number;
  /** One row, or two rows drifting in opposite directions (the list is split in half). */
  rows?: 1 | 2;
  /** Ease a row to a stop while the pointer is over it. */
  pauseOnHover?: boolean;
  /** Fade the band out at both edges with a mask. */
  fadeEdges?: boolean;
  className?: string;
};

export default function LogoCloudMarquee({
  logos = LOGOS,
  eyebrow = "Customers",
  title = "Running in production at 2,400 teams.",
  speed = 34,
  rows = 2,
  pauseOnHover = true,
  fadeEdges = true,
  className,
}: LogoCloudMarqueeProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const inView = useInView(ref);
  const half = Math.ceil(logos.length / 2);
  const lists = rows === 2 ? [logos.slice(0, half), logos.slice(half)] : [logos];
  const item = (b: Logo | null, i: number) =>
    b ? (
      <span key={`${b.name}-${i}`} className="flex items-center px-6 text-[#1d1d1f]/80 hover:text-[#1d1d1f] dark:text-[#f5f5f7]/80 dark:hover:text-[#f5f5f7]">
        <LogoLockup logo={b} tinted className="text-[19px] sm:text-[21px]" />
      </span>
    ) : null;

  return (
    <section className={cn("w-full bg-white px-4 py-16 dark:bg-black sm:py-24", className)}>
      <LogoHeading eyebrow={eyebrow} title={title} />
      <div
        ref={ref}
        className="mt-12 flex flex-col gap-8 overflow-hidden sm:mt-14"
        style={fadeEdges ? { WebkitMaskImage: EDGE, maskImage: EDGE } : undefined}
      >
        {lists.map((list, r) => (
          <Track key={r} items={list} speed={r === 0 ? speed : speed * 0.8} reverse={r === 1} render={item} gap={8} active={inView} pauseOnHover={pauseOnHover} />
        ))}
      </div>
    </section>
  );
}

"use client";
// Logo Shelf: rows of app-icon tiles scroll past on shelves, in opposite directions, with a few
// gaps so it reads like a wall of integrations. Each tile is just the brand glyph in its colour on a
// rounded square; hover lifts one on a spring. Pauses off screen, on hover and under reduced motion.

import * as React from "react";
import { motion, useInView } from "framer-motion";
import { cn } from "@/lib/utils";
import { EDGE, LOGOS, LogoHeading, Track, type Logo } from "./logos";

export type LogoCloudShelfProps = {
  /** Brands to place on the shelves: { name, Icon, color }. Defaults to twenty invented brands. */
  logos?: Logo[];
  /** Small blue label above the headline. Leave empty to hide it. */
  eyebrow?: string;
  /** Headline above the shelves. */
  title?: string;
  /** Number of shelves (1 to 5). Odd ones drift left, even ones right. */
  rows?: number;
  /** Drift speed of the first shelf, in px per second. Each next shelf is 5 faster. */
  speed?: number;
  className?: string;
};

/** Lays the brands out on the shelves with a few empty slots. A fixed seed keeps the gaps in the same places on every render and on the server. */
function buildShelves(logos: Logo[], rows: number): (Logo | null)[][] {
  let seed = 7;
  const rand = () => {
    seed = (seed * 16807) % 2147483647;
    return seed / 2147483647;
  };
  let next = 0;
  const shelves: (Logo | null)[][] = [];
  const count = Math.max(1, Math.min(5, Math.round(rows)));
  for (let r = 0; r < count; r++) {
    const shelf: (Logo | null)[] = [];
    for (let c = 0; c < 14; c++) {
      if (rand() < 0.32) {
        shelf.push(null);
        continue;
      }
      shelf.push(logos[next % logos.length]);
      next += 1 + Math.floor(rand() * 2);
    }
    shelves.push(shelf);
  }
  return shelves;
}

export default function LogoCloudShelf({
  logos = LOGOS,
  eyebrow = "Integrations",
  title = "Works with the tools your team already lives in.",
  rows = 3,
  speed = 22,
  className,
}: LogoCloudShelfProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const inView = useInView(ref);
  const shelves = React.useMemo(() => buildShelves(logos, rows), [logos, rows]);

  return (
    <section className={cn("w-full bg-white px-4 py-16 dark:bg-black sm:py-24", className)}>
      <LogoHeading eyebrow={eyebrow} eyebrowClassName="text-[#0071e3] dark:text-[#2997ff]" title={title} />
      <div
        ref={ref}
        className="mt-12 flex flex-col gap-3 overflow-hidden sm:mt-14"
        style={{ WebkitMaskImage: EDGE, maskImage: EDGE }}
      >
        {shelves.map((row, r) => (
          <Track
            key={r}
            items={row}
            speed={speed + r * 5}
            reverse={r % 2 === 1}
            gap={12}
            active={inView}
            render={(b: Logo | null, i: number) =>
              b ? (
                <motion.span
                  key={`${b.name}-${i}`}
                  role="img"
                  aria-label={b.name}
                  whileHover={{ y: -4, scale: 1.06 }}
                  transition={{ type: "spring", stiffness: 420, damping: 26 }}
                  className="flex h-16 w-16 shrink-0 items-center justify-center rounded-[18px] bg-white shadow-[0_0_0_1px_rgba(0,0,0,.06),0_8px_18px_-10px_rgba(0,0,0,.35)] dark:bg-[#2c2c2e] dark:shadow-[0_0_0_1px_rgba(255,255,255,.08)]"
                >
                  <b.Icon className="h-8 w-8" style={{ color: b.color }} />
                </motion.span>
              ) : (
                <span key={`e-${i}`} aria-hidden="true" className="h-16 w-16 shrink-0 rounded-[18px] bg-black/[0.025] shadow-[inset_0_0_0_1px_rgba(0,0,0,.04)] dark:bg-white/[0.04] dark:shadow-[inset_0_0_0_1px_rgba(255,255,255,.06)]" />
              )
            }
          />
        ))}
      </div>
    </section>
  );
}

"use client";
// Single Row Lift: the most restrained variant. The line sits on the left and one row of five marks
// rotates through the brands beside it. Hover a mark and it lifts and takes its brand colour while
// the rest of the row recedes, and the rotation holds until the pointer leaves.

import * as React from "react";
import { AnimatePresence, motion, useInView, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { INK, LOGOS, LogoLockup, SPRING, usePager, type Logo } from "./logos";

export type LogoCloudSingleRowProps = {
  /** Brands to rotate through: { name, Icon, color, wordmark? }. Defaults to twenty invented brands. */
  logos?: Logo[];
  /** The line on the left. */
  title?: string;
  /** Milliseconds between rotations. */
  interval?: number;
  /** Opacity of the other marks while one is hovered (0 to 1). */
  recedeOpacity?: number;
  /** How far the hovered mark lifts, in px. */
  lift?: number;
  className?: string;
};

export default function LogoCloudSingleRow({
  logos = LOGOS,
  title = "Product teams at these companies plan their week with us.",
  interval = 2600,
  recedeOpacity = 0.3,
  lift = 4,
  className,
}: LogoCloudSingleRowProps) {
  const ref = React.useRef<HTMLUListElement>(null);
  const inView = useInView(ref, { margin: "-80px" });
  const reduced = !!useReducedMotion();
  const [hover, setHover] = React.useState<number | null>(null);
  const { page, items } = usePager(logos, 5, Math.max(1600, interval), inView && hover === null && !reduced);

  return (
    <section className={cn("w-full bg-white px-4 py-16 dark:bg-black sm:py-24", className)}>
      <div className="mx-auto flex w-full max-w-5xl flex-col items-center gap-8 md:flex-row md:gap-10">
        {title ? (
          <p className="m-0 max-w-[15rem] text-balance text-center text-[17px] font-semibold leading-[1.35] tracking-[-0.015em] text-[#1d1d1f] dark:text-[#f5f5f7] md:shrink-0 md:border-r md:border-black/10 md:pr-10 md:text-left dark:md:border-white/15">
            {title}
          </p>
        ) : null}
        <ul
          ref={ref}
          onMouseLeave={() => setHover(null)}
          className="m-0 grid w-full list-none grid-cols-2 gap-6 p-0 sm:grid-cols-3 md:flex md:flex-1 md:justify-between"
        >
          {items.map((b, i) => (
            <motion.li
              key={i}
              onHoverStart={() => setHover(i)}
              animate={{
                opacity: hover === null ? 0.82 : hover === i ? 1 : recedeOpacity,
                y: hover === i && !reduced ? -lift : 0,
                scale: hover === i && !reduced ? 1.06 : 1,
              }}
              transition={SPRING}
              className={cn("relative flex h-12 items-center justify-center", INK)}
            >
              <AnimatePresence mode="popLayout" initial={false}>
                <motion.span
                  key={`${page}-${b.name}`}
                  role="img"
                  aria-label={b.name}
                  initial={reduced ? { opacity: 0 } : { opacity: 0, y: 14, filter: "blur(8px)" }}
                  animate={{ opacity: 1, y: 0, filter: "blur(0px)", transition: { ...SPRING, delay: i * 0.06 } }}
                  exit={reduced ? { opacity: 0 } : { opacity: 0, y: -14, filter: "blur(8px)", transition: { ...SPRING, delay: i * 0.06 } }}
                >
                  <LogoLockup logo={b} tinted={hover === i} className="text-[17px] sm:text-[19px]" />
                </motion.span>
              </AnimatePresence>
            </motion.li>
          ))}
        </ul>
      </div>
    </section>
  );
}

"use client";
// Cursor Spotlight: a panel of twelve brands in a hairline grid. They sit dim and grey, and a soft
// light follows the pointer: inside it each lockup turns to full ink with its brand colour. The
// light chases the pointer on a spring. With `autoplay` it drifts along a slow figure-eight by
// itself until the first touch, and it stops drifting off screen.

import * as React from "react";
import { motion, useAnimationFrame, useInView, useMotionTemplate, useMotionValue, useReducedMotion, useSpring } from "framer-motion";
import { cn } from "@/lib/utils";
import { INK, LOGOS, LogoHeading, LogoLockup, type Logo } from "./logos";

export type LogoCloudSpotlightProps = {
  /** Brands in the grid: { name, Icon, color, wordmark? }. Defaults to twenty invented brands (the first twelve show). */
  logos?: Logo[];
  /** Headline above the panel. */
  title?: string;
  /** Line under the headline. Leave empty to hide it. */
  subtitle?: string;
  /** Radius of the light, in px. */
  radius?: number;
  /** Drifts the light along a figure-eight by itself until someone touches the panel. Pauses off screen and never runs under reduced motion. */
  autoplay?: boolean;
  className?: string;
};

export default function LogoCloudSpotlight({
  logos = LOGOS,
  title = "Twelve partners, one integration standard.",
  subtitle = "Move across the grid to light up each partner.",
  radius = 200,
  autoplay = false,
  className,
}: LogoCloudSpotlightProps) {
  const reduced = !!useReducedMotion();
  const panel = React.useRef<HTMLDivElement>(null);
  const inView = useInView(panel);
  const touched = React.useRef(false);
  const pointerIn = React.useRef(false);
  const mx = useMotionValue(-999);
  const my = useMotionValue(-999);
  const x = useSpring(mx, { stiffness: 220, damping: 28, mass: 0.6 });
  const y = useSpring(my, { stiffness: 220, damping: 28, mass: 0.6 });
  const mask = useMotionTemplate`radial-gradient(circle ${radius}px at ${x}px ${y}px, black 0%, transparent 72%)`;
  const list = logos.slice(0, 12);

  useAnimationFrame((t) => {
    const el = panel.current;
    if (!el || pointerIn.current || !inView) return;
    if (!autoplay || reduced || touched.current) {
      mx.set(el.clientWidth / 2);
      my.set(el.clientHeight / 2);
      return;
    }
    // drift the light along a slow figure-eight so the panel demos itself
    mx.set(el.clientWidth * (0.5 + 0.38 * Math.sin(t / 1300)));
    my.set(el.clientHeight * (0.5 + 0.3 * Math.sin(t / 650)));
  });

  const grid = (lit: boolean) => (
    <div
      aria-hidden={lit ? true : undefined}
      className="grid grid-cols-2 gap-px overflow-hidden rounded-[18px] bg-black/[0.06] dark:bg-white/[0.08] sm:grid-cols-4"
    >
      {list.map((b) => (
        <div
          key={b.name}
          className={cn(
            "flex h-[84px] items-center justify-center bg-white dark:bg-[#1c1c1e]",
            lit ? INK : "text-[#1d1d1f]/30 dark:text-[#f5f5f7]/30",
          )}
        >
          <LogoLockup logo={b} tinted={lit} className="text-[16px] sm:text-[18px]" />
        </div>
      ))}
    </div>
  );

  return (
    <section className={cn("w-full bg-white px-4 py-16 dark:bg-black sm:py-24", className)}>
      <LogoHeading title={title} subtitle={subtitle} />
      <div
        ref={panel}
        onMouseMove={(e) => {
          pointerIn.current = true;
          touched.current = true;
          const r = e.currentTarget.getBoundingClientRect();
          mx.set(e.clientX - r.left);
          my.set(e.clientY - r.top);
        }}
        onMouseLeave={() => (pointerIn.current = false)}
        className="relative mx-auto mt-12 max-w-3xl overflow-hidden rounded-[24px] bg-white p-2 shadow-[0_0_0_1px_rgba(0,0,0,.05),0_20px_40px_-26px_rgba(0,0,0,.35)] dark:bg-[#1c1c1e] dark:shadow-[0_0_0_1px_rgba(255,255,255,.08)] sm:mt-14"
      >
        {grid(false)}
        <motion.div className="pointer-events-none absolute inset-0 p-2" style={{ WebkitMaskImage: mask, maskImage: mask }}>
          {grid(true)}
        </motion.div>
      </div>
    </section>
  );
}

"use client";
// Swap Animation: ten slots show one page of brands at a time. Every `interval` ms the next page
// slides through from the right, slot by slot: each outgoing lockup slides left and blurs out while
// the incoming one arrives from the right. Pauses on hover and while off screen.

import * as React from "react";
import { AnimatePresence, motion, useInView, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { INK, LOGOS, LogoHeading, LogoLockup, SPRING, usePager, type Logo } from "./logos";

export type LogoCloudSwapProps = {
  /** Brands to page through: { name, Icon, color, wordmark? }. Defaults to twenty invented brands. */
  logos?: Logo[];
  /** Headline above the grid. */
  title?: string;
  /** Line under the headline. Leave empty to hide it. */
  subtitle?: string;
  /** Milliseconds between pages. */
  interval?: number;
  /** Delay between one slot and the next, in seconds. */
  stagger?: number;
  className?: string;
};

export default function LogoCloudSwap({
  logos = LOGOS,
  title = "Chosen by teams who sweat the details",
  subtitle = "Each of these replaced three tools with one.",
  interval = 3000,
  stagger = 0.05,
  className,
}: LogoCloudSwapProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const inView = useInView(ref, { margin: "-80px" });
  const reduced = !!useReducedMotion();
  const [held, setHeld] = React.useState(false);
  const { page, items } = usePager(logos, 10, interval, inView && !held && !reduced);

  return (
    <section className={cn("w-full bg-white px-4 py-16 dark:bg-black sm:py-24", className)}>
      <LogoHeading title={title} subtitle={subtitle} />
      <div
        ref={ref}
        onMouseEnter={() => setHeld(true)}
        onMouseLeave={() => setHeld(false)}
        className="mx-auto mt-12 grid max-w-4xl grid-cols-2 gap-x-4 gap-y-5 sm:mt-14 sm:grid-cols-5"
      >
        {items.map((b, i) => (
          <div key={i} className={cn("relative flex h-14 items-center justify-center opacity-80 hover:opacity-100", INK)}>
            <AnimatePresence mode="popLayout" initial={false}>
              <motion.span
                key={`${page}-${b.name}`}
                role="img"
                aria-label={b.name}
                initial={reduced ? { opacity: 0 } : { opacity: 0, x: 40, filter: "blur(8px)" }}
                animate={{ opacity: 1, x: 0, filter: "blur(0px)", transition: { ...SPRING, delay: i * stagger } }}
                exit={reduced ? { opacity: 0 } : { opacity: 0, x: -40, filter: "blur(8px)", transition: { ...SPRING, delay: i * stagger } }}
              >
                <LogoLockup logo={b} className="text-[17px] sm:text-[19px]" />
              </motion.span>
            </AnimatePresence>
          </div>
        ))}
      </div>
    </section>
  );
}

"use client";
// Blur Flip Grid: eight marks hold their places in a quiet grid. Every `interval` ms each slot rolls
// over to the next brand, one after another: the old lockup tips back and blurs away while the new
// one springs up from below. Transforms, opacity and blur only, so nothing around it shifts. Pauses
// while off screen and never runs under reduced motion.

import * as React from "react";
import { AnimatePresence, motion, useInView, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { INK, LOGOS, LogoHeading, LogoLockup, SPRING, usePager, type Logo } from "./logos";

export type LogosBlurFlipProps = {
  /** Brands to roll through: { name, Icon, color, wordmark? }. Defaults to twenty invented brands. */
  logos?: Logo[];
  /** Headline above the grid. */
  title?: string;
  /** Line under the headline. Leave empty to hide it. */
  subtitle?: string;
  /** Milliseconds between flips. Each slot follows the one before by 70ms. */
  interval?: number;
  className?: string;
};

export default function LogosBlurFlip({
  logos = LOGOS,
  title = "Used by teams that ship every week",
  subtitle = "From two-person studios to platform teams of four hundred.",
  interval = 3000,
  className,
}: LogosBlurFlipProps) {
  const ref = React.useRef<HTMLUListElement>(null);
  const inView = useInView(ref, { margin: "-80px" });
  const reduced = !!useReducedMotion();
  const { page, items } = usePager(logos, 8, interval, inView && !reduced);

  return (
    <section className={cn("w-full bg-white px-4 py-16 dark:bg-black sm:py-24", className)}>
      <LogoHeading title={title} subtitle={subtitle} />
      <ul ref={ref} className="m-0 mx-auto mt-12 grid max-w-3xl list-none grid-cols-2 gap-x-6 gap-y-4 p-0 sm:mt-14 sm:grid-cols-4">
        {items.map((b, i) => (
          <li key={i} className={cn("relative flex h-16 items-center justify-center opacity-80 [perspective:700px] hover:opacity-100", INK)}>
            <AnimatePresence mode="popLayout" initial={false}>
              <motion.span
                key={`${page}-${b.name}`}
                role="img"
                aria-label={b.name}
                initial={reduced ? { opacity: 0 } : { opacity: 0, rotateX: 80, y: "45%", filter: "blur(8px)" }}
                animate={{ opacity: 1, rotateX: 0, y: 0, filter: "blur(0px)", transition: { ...SPRING, delay: i * 0.07 } }}
                exit={reduced ? { opacity: 0 } : { opacity: 0, rotateX: -80, y: "-45%", filter: "blur(8px)", transition: { ...SPRING, delay: i * 0.07 } }}
              >
                <LogoLockup logo={b} className="text-[19px] sm:text-[21px]" />
              </motion.span>
            </AnimatePresence>
          </li>
        ))}
      </ul>
    </section>
  );
}

"use client";

